input.newString:
// Ref callbacks that call setState (e.g. Slate/Plate registering editor nodes) used to
// re-run on every re-render because Slot created a new composed ref identity per render:
// reattach -> setState -> re-render -> new ref identity -> reattach -> ... -> "Maximum
// update depth exceeded". The composed ref must keep a stable identity so the callback
// runs once, not on every update.
render(<CountingInput />);
const input = screen.getByRole('textbox');
await userEvent.type(input, 'foo');
expect(input).toHaveValue('foo');
expect(input.getAttribute('data-ref-calls')).toBe('1');

